<script setup lang="ts">import { computed, onMounted, ref } from 'vue';import { ChevronRight, LockKeyhole, Moon, Trash2 } from 'lucide-vue-next';import AppShell from '@/components/AppShell.vue';import { loadProfile, profile, type NemuSession } from '@/services/auth-service';import { applyTheme, currentTheme } from '@/services/theme-service';const dark=ref(currentTheme()==='dark');const account=ref<Pick<NemuSession,'email'|'displayName'|'avatarUrl'>|undefined>(profile());const initial=computed(()=>account.value?.displayName?.trim().charAt(0).toUpperCase()||account.value?.email.charAt(0).toUpperCase()||'?');onMounted(async()=>{try{account.value=await loadProfile()}catch{/* Existing local profile remains visible if offline. */}});function toggle(){dark.value=!dark.value;applyTheme(dark.value?'dark':'light')}</script>
<template><AppShell><div class="page"><header><p class="text-sm font-medium text-nemu-600 dark:text-[#83d8b2]">Preferences</p><h1 class="mt-2 text-3xl font-semibold tracking-[-.035em]">Settings</h1></header><section class="mt-8"><p class="px-1 text-xs font-semibold uppercase tracking-[.12em] text-muted">Account</p><div class="surface mt-3 overflow-hidden rounded-2xl border border-line"><button class="flex w-full items-center gap-3 p-4 text-left"><img v-if="account?.avatarUrl" :src="account.avatarUrl" alt="Foto profil Google" class="size-10 rounded-full object-cover"/><span v-else class="grid size-10 place-items-center rounded-full bg-[#f0c8ad] text-sm font-bold text-[#714328]">{{ initial }}</span><span class="flex-1"><span class="block font-semibold">{{ account?.displayName || 'Akun Google' }}</span><span class="block text-sm text-muted">{{ account?.email || 'Masuk ulang untuk melihat akun' }}</span></span><ChevronRight :size="19" class="text-muted"/></button></div></section><section class="mt-8"><p class="px-1 text-xs font-semibold uppercase tracking-[.12em] text-muted">Security</p><div class="surface mt-3 overflow-hidden rounded-2xl border border-line"><button class="flex w-full items-center gap-3 border-b border-line p-4 text-left"><LockKeyhole :size="19" class="text-muted"/><span class="flex-1 font-medium">Biometric lock</span><span class="text-sm text-muted">Off</span><ChevronRight :size="19" class="text-muted"/></button><button class="flex w-full items-center gap-3 p-4 text-left" @click="toggle"><Moon :size="19" class="text-muted"/><span class="flex-1 font-medium">Dark mode</span><span class="text-sm text-muted">{{dark?'On':'Off'}}</span></button></div></section><section class="mt-8"><p class="px-1 text-xs font-semibold uppercase tracking-[.12em] text-muted">Data</p><div class="surface mt-3 overflow-hidden rounded-2xl border border-line"><RouterLink to="/trash" class="flex items-center gap-3 p-4"><Trash2 :size="19" class="text-muted"/><span class="flex-1 font-medium">Trash</span><ChevronRight :size="19" class="text-muted"/></RouterLink></div></section><p class="mt-9 text-center text-xs leading-5 text-muted">Memory kamu bersifat pribadi.<br/>NEMU v0.1</p></div></AppShell></template>
